const edition = globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2013,"grade":"9-11","contest":"Золотое руно","letters":"ABC","count":60,"language":"kk","points":3,"tasksFile":"ZR_1213_KZ_9-11.pdf","answersFile":"reviewed-9-11-vkz.pdf","title":"Pax Germanica. Единство немецкой стихии","sourceFile":"sources/golden-fleece/2013/interactive-9-11-vkz.json","sections":[{"start":1,"title":"Тарих"},{"start":16,"title":"Әдебиет"},{"start":31,"title":"Күнделікті мәдениет"},{"start":46,"title":"Көркем мәдениет"}],"variant":"kz","editionSuffix":"vkz","editionLabel":"На казахском языке","reviewedKey":true}, [{"number":1,"question":"В1814-1815жылғы Вена конгресінің шешімінен Пруссия не ұтты?","choices":["Рейн облысын қайтарып алды","Польшадағы иеліктерін толықтай қайтарып алды","Герман одағын басқаратын болды"],"answer":0,"title":"Пруссия после конгресса","steps":["Венский конгресс перераспределил земли после наполеоновских войн. Пруссия приобрела значительную часть Рейнской области и Вестфалии.","Из вариантов верен тот, где названа Рейнская область."]},{"number":2,"question":"О.фон Бисмарк «культуркампф» саясатын қандай мақсатпен жүргізді?","choices":["Герман мектептеріндегі білім беру сапасын арттыру","Германиядағы католицизмнің ықпалын әлсірету","Германиядағы мәдениет деңгейін көтеру"],"answer":1,"title":"Политика против влияния","steps":["Правительство Бисмарка усиливало государственный контроль за школами, духовенством и церковными назначениями.","Культуркампф был направлен на ослабление политического влияния католической церкви."]},{"number":3,"question":"Речь Посполитаның бірінші тарауы 1772 жылы Пруссия үшін қандай басты нәтиже берді?","choices":["Польша тарапынан төнген қауіптен қорғану","Шығыс Еуропадағы жер аумағын қосу","Ресеймен ортақ шекараға ие болу"],"answer":1,"title":"Первый раздел государства","steps":["Соседние монархии поделили часть земель Речи Посполитой. Пруссия получила территории, позволившие соединить её восточные владения с основной частью.","Результат для Пруссии — присоединение земель Восточной Европы."]},{"number":4,"question":"Кванттық механиканы жасап шығарғандығы үшін Нобель сыйлығын алған неміс физигі.","choices":["В. Вин","В. Гейзенберг","В. К. Рентген"],"answer":1,"title":"Квантовая механика","steps":["Нобелевскую премию за 1932 год присудили за разработку квантовой механики. Матричная форма теории и принцип неопределённости связаны с одним учёным.","Это Вернер Гейзенберг."]},{"number":5,"question":"ВИмператордың уақытша тұратын жері болып бекітілген қамал-үй-жайы орта ғасырларда қалай аталды?","choices":["«бург»","«пфальц»","«штадт»"],"answer":1,"title":"Двор на время","steps":["Средневековые императоры не имели одной постоянной столицы. В дороге они останавливались в укреплённых усадьбах, где держали запасы и принимали подданных.","Такую резиденцию называли пфальцем."]},{"number":6,"question":"Бірінші дүниежүзілік соғыстан кейін екі мемлекетке де тең құқылы бірінші халықаралық келісім болып табылатын 1922 жылы қол қойылған РСФРО мен Веймар республикасы арасындағы келісім-шарт қандай қалада жасалды?","choices":["Брест","Нюрнберг","Рапалло"],"answer":2,"title":"Договор двух республик","steps":["На фоне Генуэзской конференции Германия и Советская Россия восстановили дипломатические отношения и отказались от взаимных претензий.","Отдельное соглашение подписали в Рапалло."]},{"number":7,"question":"Бірінші дүниежүзілік соғыс басталғаннан кейін рейхстагта сөйлеген сөзінде ІІ Вильгельм не деді?","choices":["«Сарбаздар ағаштағы жапырақтар түскенге дейін қайтып оралады»","«Мен енді ешқандай партия дегенді білмеймін. Мен үшін тек немістер ғана бар!»","«Жаратқан менің қаруыма жеңіс берсін»"],"answer":1,"title":"Речь в начале войны","steps":["Перед голосованием о военных кредитах император призвал партию и общество отказаться от раздоров. В Германии это называлось политикой гражданского мира.","Поэтому он сказал, что теперь знает только немцев, а партий больше не знает."]},{"number":8,"question":"1828 жылдан 1949 жылға дейін ІІІ Фридрих Вильгельмнің атында болған Берлин университеті қандай неміс ғалымының бастамасымен негізі қаланған еді?","choices":["И. Кант","В. Гумбольдт","Г. Гегель"],"answer":1,"title":"Замысел университета","steps":["В 1810 году в Берлине открыли университет, где обучение связывали с самостоятельной исследовательской работой.","Проект реформы разработал Вильгельм Гумбольдт."]},{"number":9,"question":"Австрия Германияға қашан қосылды?","choices":["Екінші дүниежүзілік соғыстың алдында","Екінші дүниежүзілік соғыс кезінде","Екінші дүниежүзілік соғыс аяқталған соң"],"answer":0,"title":"Время аншлюса","steps":["Германия присоединила Австрию в марте 1938 года. Война в Европе началась в сентябре 1939 года.","Аншлюс произошёл до её начала."]},{"number":10,"question":"Екінші дүниежүзілік соғыс жылдарында Ұлттар Лигасының штаб-пәтері қайда орналасқан?","choices":["Лихтенштейн","Австрия","Швейцария"],"answer":2,"title":"Место Лиги Наций","steps":["Лига Наций работала в Женеве. Её Дворец Наций достроили перед Второй мировой войной.","Женева находится в Швейцарии."]},{"number":11,"question":"Бірінші дүниежүзілік соғыс кезінде болған ірі шайқастың бірі төмендегі қай орыс қолбасшысының атымен аталған?","choices":["А. И. Деникин","А. А. Брусилов","М. В. Алексеев"],"answer":1,"title":"Имя наступления","steps":["Юго-Западный фронт в 1916 году прорвал укрепления австро-венгерской армии. Наступление называли по фамилии его командующего.","Это Брусиловский прорыв, названный в честь Алексея Брусилова."]},{"number":12,"question":"Екінші дүниежүзілік соғыс неміс әскерлерінің қай елге басып кіруінен басталды?","choices":["КСРО","Польша","Франция"],"answer":1,"title":"Вторжение 1939 года","steps":["Германская армия перешла границу соседней страны 1 сентября. Через два дня Великобритания и Франция объявили Германии войну.","Вторжение в Польшу принято считать началом Второй мировой войны в Европе."]},{"number":13,"question":"«Сенің бар күш-жігерің кез-келген уақытта жалпыға бірдей заңдылықтар қағидасының күшіне ие болатындай іс-әрекет жаса» деген сөзді қандай философ айтқан.","choices":["К. Маркс","Г. Гегель","И. Кант"],"answer":2,"title":"Всеобщий принцип","steps":["Философ предлагает проверять личное правило: могло бы оно стать законом для всех людей?","Так Иммануил Кант формулировал категорический императив."]},{"number":14,"question":"Тильзит шартының мәтініне сай, Наполеон Пруссияға жер аумағының бір бөлігін кімге деген құрметі үшін қайтарды?","choices":["марқұм ІІ Фридрихқа","Пруссия сарбаздарының ерлігіне","орыс императорына"],"answer":2,"title":"Оговорка Тильзита","steps":["После побед над Пруссией Наполеон договорился с Александром I. Уважением к российскому монарху объяснили сохранение части прусских земель.","В договоре речь о русском императоре."]},{"number":15,"question":"Ғұндарға қарсы болған Каталаун даласындағы шайқаста рим, вестгот және басқа да герман тайпаларынан құралған әскери одақты басқарған қолбасшы.","choices":["Аттила","Флавий Аэций","Гай Юлий Цезарь"],"answer":1,"title":"Коалиция против гуннов","steps":["В 451 году римские войска с вестготами остановили гуннов Аттилы в Галлии. Римский полководец смог привлечь германских союзников.","Командующего звали Флавий Аэций."]},{"number":16,"question":"Христиан королі мен еврей қызы арасындағы махаббат туралы Л.Фейхтвангердің тарихи романы қалай аталады?","choices":["«Еврей Зюсс»","«Иеффай мен оның қызы»","«Испан балладасы»"],"answer":2,"title":"Король и девушка","steps":["Роман рассказывает об Альфонсо VIII Кастильском и еврейской девушке Ракели. Сюжет основан на легенде о любви при испанском дворе.","Книга Фейхтвангера известна как «Испанская баллада»."]},{"number":17,"question":"Ұлы голландиялық суретші Рембрандтқа өлең жолдарымен жазылған повесть арнаған неміс жазушысы кім?","choices":["Г. фон Клейст","И. В. Гёте","А. фон Арним"],"answer":2,"title":"Повесть о живописце","steps":["Немецкий романтик создал историю о художнике Рембрандте. Он собирал старые песни и легенды и включал их мотивы в прозу.","Это Ахим фон Арним."]},{"number":18,"question":"Соңғы драмасын орыстың оқиғасының желісі бойынша жазған неміс жазушысы кім?","choices":["Ф. Шиллер","Г. фон Клейст","И. В. Гёте"],"answer":0,"title":"Незавершённая драма","steps":["Действие последней незавершённой драмы писателя связано со Смутным временем и претендентом на русский престол. Она называется «Деметриус».","Над ней работал Фридрих Шиллер."]},{"number":19,"question":"«Жаздың түніндегі ұйқы» атты В.Шекспирдің комедиясындағы кейіпкерлер Оберон мен Титания И.В.Гётенің қандай шығармасында кездеседі?","choices":["«Эгмонт»","«Фауст»","«Орман патшасы»"],"answer":1,"title":"Оберон и Титания","steps":["Гёте поместил заимствованных у Шекспира героев в интермедию о золотой свадьбе короля и королевы фей.","«Сон в Вальпургиеву ночь» входит в трагедию «Фауст»."]},{"number":20,"question":"Композитор Р.Шуман қандай неміс жазушысының ықпалымен әдеби туындылар жаза бастады, сондай-ақ фортепианада ойналатын алғашқы сюитасын шығарды?","choices":["Ф. Шиллер","Жан-Поль","И. В. Гёте"],"answer":1,"title":"Книга для музыканта","steps":["В юности Шуман увлекался романом «Озорные годы» и другими книгами немецкого писателя. Литературная игра с характерами подсказала ему сюиту «Бабочки».","Любимым автором был Жан-Поль."]},{"number":21,"question":"И.Северянин «ол бізге Евангелие сияқты қажет» деп қай неміс жазушысы туралы жазған?","choices":["Р. М. Рильке","Э. М. Ремарк","Ф. Ницше"],"answer":1,"title":"Писатель в стихах","steps":["Северянин размышлял о литературе, которая заставляла помнить о разрушительной силе войны. Одной из главных книг с таким воздействием был роман «На западном фронте без перемен».","В стихотворном обращении он назвал необходимым Эриха Марию Ремарка."]},{"number":22,"question":"Ата-аналарының Үндістанда тұруы оның Шығыс елдеріне деген қызығушылығын оятқан және бұл оның шығармаларынан да көрініс тапқан. Сөз болып отырған неміс жазушысы кім?","choices":["Л. Фейхтвангер","Г. Гессе","Т. Манн"],"answer":1,"title":"Интерес к Востоку","steps":["Писатель вырос в семье, связанной с миссионерской работой и изучением Индии. Позднее он написал повесть о духовных поисках Сиддхартхи.","Индийские мотивы занимают большое место у Германа Гессе."]},{"number":23,"question":"Неміс ұлттық театры жанынан ашылған журналдың негізін қалаған жазушы кім?","choices":["Жан-Поль","Ф. Шиллер","Г. Э. Лессинг"],"answer":2,"title":"Журнал при театре","steps":["Критик писал о постановках нового театра в Гамбурге и о том, как строится действие пьесы. Заметки вошли в «Гамбургскую драматургию».","Их автор — Готхольд Эфраим Лессинг."]},{"number":24,"question":"Т.Манның «Доктор Фауст» романындағы басты кейіпкер мамандығы бойынша кім болды?","choices":["Композитор","Ғалым","Жазушы"],"answer":0,"title":"Профессия Фаустуса","steps":["Герой Томаса Манна заключает символическое соглашение в обмен на годы творческой силы. Он создаёт музыкальные произведения и обсуждает теорию музыки.","Адриан Леверкюн — композитор."]},{"number":25,"question":"Ф.Лист пен Н.Паганинидің әдеби портреттерін қалдырған неміс романтигі кім?","choices":["Г. фон Клейст","Г. Гейне","Э. Т. А. Гофман"],"answer":1,"title":"Два виртуоза","steps":["В газетных очерках «Лютеция» писатель описывал европейскую музыкальную жизнь, в том числе выступления и впечатление от артистов.","Литературные портреты Листа и Паганини принадлежат Генриху Гейне."]},{"number":26,"question":"Т.Манн «Лотта Веймарда» романында немістің қай жазушысының өміріндегі шынайы романтикалық оқиғаларды жазды?","choices":["И. В. Гёте","Жан-Поль","Ф. Шиллер"],"answer":0,"title":"История в Веймаре","steps":["Героиня романа — Шарлотта Буфф, которую молодой писатель сделал одним из прообразов Лотты в романе о Вертере.","Старого знакомого в Веймаре зовут Иоганн Вольфганг Гёте."]},{"number":27,"question":"Л.Толстоймен кездесіп, М.Цветаевамен хат жазысып тұрған австриялық әдебиетші кім?","choices":["Р. М. Рильке","С. Цвейг","Г. фон Гофмансталь"],"answer":0,"title":"Русские встречи","steps":["Поэт путешествовал по России и посетил Ясную Поляну. Спустя годы он переписывался с Цветаевой и Пастернаком.","Это Райнер Мария Рильке."]},{"number":28,"question":"Э.М.Ремарктің «Батыс майданда өзгеріс жоқ» романы қандай оқиғаларға арналған?","choices":["Франк-прусс соғысына","Бірінші дүниежүзілік соғысқа","Екінші дүниежүзілік соғысқа"],"answer":1,"title":"Время действия романа","steps":["Немецкие школьники идут на фронт по призыву учителя. Герой описывает жизнь солдат на Западном фронте до 1918 года.","События относятся к Первой мировой войне."]},{"number":29,"question":"Бұл орыс ақынының әдеби мұрасының көп бөлігі неміс романтикалық поэзиясының аудармаларынан тұрады, ал А.Пушкин оны «аударма данышпаны» деп атаған. Кім жайлы сөз болып отыр?","choices":["Ф. Тютчев","Г. Державин","В. Жуковский"],"answer":2,"title":"Переводы немецких баллад","steps":["Поэт переводил Бюргера, Шиллера и Гёте, меняя форму стихотворений для русских читателей. Пушкин ценил его художественную самостоятельность.","Такое место в поэзии занял Василий Жуковский."]},{"number":30,"question":"Дипломатиялық корпуста жұмыс істеген, өмірінің көп бөлігін Германияда өткізген және Г.Гейнені ең алғаш орыс тіліне аударған орыс ақыны кім?","choices":["В. Жуковский","Г. Державин","Ф. Тютчев"],"answer":2,"title":"Поэт и дипломат","steps":["Русский поэт служил в дипломатических миссиях в Мюнхене и Турине. В германской среде он познакомился с Гейне.","Фёдор Тютчев одним из первых переводил Гейне на русский язык."]},{"number":31,"question":"Арасында А.Коссель, К.Бош, Р.Куп болған, Нобель сыйлығының лауреаттары атанған түлектерімен және оқытушыларымен танымал университет.","choices":["Фрайбург","Гейдельберг","Бонн"],"answer":1,"title":"Три лауреата","steps":["Коссель занимался биохимией, Бош — промышленной химией, Кун — строением органических веществ. Все связаны с одним университетским городом на Неккаре.","Это Гейдельберг."]},{"number":32,"question":"Қазіргі күмбезінің жобасын британ сәулетшісі Н.Фостер жасаған қандай ғимарат? Соның арқасында неміс бундестагы адам ең көп баратын парламент болып отыр.","choices":["Рейхстаг ғимараты","Қызыл ратуша","Шарлоттенбург сарайы"],"answer":0,"title":"Стеклянный купол","steps":["Фостер сделал над залом заседаний стеклянный купол со спиральными пандусами. Посетители поднимаются над местом работы депутатов.","Купол расположен на здании рейхстага в Берлине."]},{"number":33,"question":"Бильярд ойнауды өте жақсы көрген вена классиктерінің бірі.","choices":["Й.Гайди","В.А.Моцарт","Л.ван Бетховен"],"answer":1,"title":"Бильярдный стол","steps":["Один из венских классиков держал бильярд дома и играл с гостями. Об этом известно из семейных свидетельств.","Хозяином бильярдного стола был Вольфганг Амадей Моцарт."]},{"number":34,"question":"Тұңғыш Байрейт фестиваліне және «Нибелунгтер сақинасы» тетралогиясынан қойылған Р.Вагнер операсының алғашқы қойылымына «Орыс ведомостілері» газетінің корреспонденті ретінде келген ұлы орыс композиторы кім?","choices":["М.Мусоргский","А.Бородин","П.Чайковский"],"answer":2,"title":"Репортаж с премьеры","steps":["Русский композитор побывал на Байрейтском фестивале летом 1876 года и присылал в газету заметки о постановках Вагнера.","Корреспондентом «Русских ведомостей» был Пётр Чайковский."]},{"number":35,"question":"Потсдамға жақын жерде орналасқан орыс ауылының атауы қандай императордың құрметіне аталған?","choices":["І Петр","І Александр","І Павел"],"answer":1,"title":"Название поселения","steps":["Прусский король устроил под Потсдамом посёлок для русских певчих. Название «Александровка» напоминает о его российском союзнике.","Поселение посвящено Александру I."]},{"number":36,"question":"Германияның екі жоғарғы сатыдағы соты орналасқан қала.","choices":["Нюрнберг","Потсдам","Карлсруэ"],"answer":2,"title":"Город двух судов","steps":["Здесь находятся Федеральный конституционный суд и Федеральная судебная палата. Город расположен в земле Баден-Вюртемберг.","Обе инстанции размещены в Карлсруэ."]},{"number":37,"question":"Бір кездері әлемдегі ең биік ғимарат болып есептеліп, Екінші дүниежүзілік соғыс кезінде жартылай қираған, ал қазіргі таңда қала көрінісін тамашалайтын бақылау алаңының қызметін атқарып тұрған шіркеу.","choices":["Мюнхендегі Фрауэнкирхе","Любектегі Әулие Мария","Гамбургтегі Әулие Николай"],"answer":2,"title":"Башня как мемориал","steps":["После бомбардировок от храма осталась высокая башня. Сейчас её используют как мемориал и смотровую площадку.","Это церковь Святого Николая в Гамбурге."]},{"number":38,"question":"Сол аймақтағы басқа да көптеген ғибадатханалар осы шіркеудің үлгісінде салынғандықтан, оны «солтүстік герман кірпіш готикасының анасы» деп атайды. Бұл қандай шіркеу?","choices":["Берлиндегі Әулие Николай","Любектегі Әулие Мария","Мюнхендегі Фрауэнкирхе"],"answer":1,"title":"Церковь из кирпича","steps":["В северогерманских городах крупные храмы строили из кирпича. Высокий любекский храм с двумя западными башнями стал для них образцом.","Эту роль сыграла церковь Святой Марии."]},{"number":39,"question":"Жоғарғы жағында жан-жақты тамашалайтын алаңы бар, ал орыс ақыны Саша Черный «оның үлкендігі пілдің бойындай» деп сипаттаған ескерткіш құрылыс.","choices":["Бремендегі Роландқа арналған ескерткіш","Мюнхендегі «Бавария» статуясы","Берлиндегі Триумф колоннасы"],"answer":1,"title":"Внутри статуи","steps":["На фото высокая женская фигура с венком и львом у ног. Внутренняя лестница ведёт к отверстиям в её голове.","Это статуя «Бавария» у мюнхенского Луга Терезы."]},{"number":40,"question":"Ф.Мендельсонның үйлену тойына арналған атақты маршы қандай шығарманың бір бөлігі болып табылады?","choices":["«Сарбаздың махаббаты»","«Гебридтер»","«Жаздың түніндегі ұйқы»"],"answer":2,"title":"Марш из пьесы","steps":["Композитор написал музыку к комедии Шекспира, где свадьбу устраивают на фоне волшебных лесных событий. Торжественный марш звучит в конце.","Марш входит в музыку к «Сну в летнюю ночь»."]},{"number":41,"question":"Вена алаңындағы екі үйді қосып тұрған сағаттың сандары 12 тарихи тұлғаның мүсіндерімен безендірілген. Бұл қандай сағат?","choices":["«Жер шары» сағаты","Анкерур сағаты","Цайт Глоккентурм мұнарасындағы сағат"],"answer":1,"title":"Часы между домами","steps":["На месте обычных стрелок по шкале проходят фигуры. Раз в день все двенадцать появляются вместе.","Часы называются Анкерур, по имени заказчика, страхового общества «Анкер»."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/41.webp","alt":"Часы между домами · 41-тапсырмаға сурет · Сол нысанның басқа фотосуреті","caption":"41-тапсырмаға сурет · Сол нысанның басқа фотосуреті","detailSrc":"assets/golden-fleece/2013/interactive-9-11-kz/41-detail.webp","width":620,"height":620}},{"number":42,"question":"Неміс ғалымы және жазушысы Т.Фонтаненің экспедиция кезінде әбден желініп қалған сол жақ аяқ киімі өлкетанушының кабинетте отыратын барлық ғалымдарға деген сын-сықағы ретінде қойылған. Бұл жәдігер қай мұражайда орналасқан?","choices":["Жасанды бұйымдар мұражайы","Өтіріктер мұражайы","Жаратылыстану мұражайы"],"answer":1,"title":"Ботинок как экспонат","steps":["Экспонаты этого музея поданы всерьёз, хотя сопровождающие истории намеренно вымышлены. Задача — заметить игру с доверием к музейной витрине.","Так устроен Музей лжи."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/42.webp","alt":"Ботинок как экспонат · 42-тапсырмаға сурет","caption":"42-тапсырмаға сурет","width":114,"height":89}},{"number":43,"question":"Мына суретте берілген мұражай Нерот неміс коммунасының атын шығарған қандай құрылғыларға арналған?","choices":["Тышқан аулағыштар","Жерде тұратын таразылар","Ет тартқыштар"],"answer":0,"title":"Промысел Нерота","steps":["Жители Нерота делали металлические приспособления для ловли грызунов и продавали их на ярмарках. Музей хранит разные конструкции.","Эти приспособления — мышеловки."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/43.webp","alt":"Промысел Нерота · 43-тапсырмаға сурет","caption":"43-тапсырмаға сурет","width":114,"height":89}},{"number":44,"question":"Каролингтер сәулет өнері туындыларының ішінде жақсырақ сақталған кіре беріс қақпадағы кішкентай шіркеу қай ғибадатхана кешенінің аумағында орналасқан?","choices":["Кведлинбург аббаттығы","Верден аббаттығы","Лорш монастырі"],"answer":2,"title":"Ворота Каролингов","steps":["Небольшое двухэтажное здание с тремя арками оформлено цветным камнем. Оно сохранилось от монастыря времён Карла Великого.","Здание известно как надвратный зал Лоршского монастыря."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/44.webp","alt":"Ворота Каролингов · 44-тапсырмаға сурет","caption":"44-тапсырмаға сурет","width":114,"height":88}},{"number":45,"question":"Маңайында емдеу мекемесі, хоспис және балабақша бар монастырь.","choices":["Мариенталь монастырі","Әулие Галл монастырі","Ленин монастырі"],"answer":2,"title":"Монастырь и уход","steps":["Бывшее цистерцианское аббатство в Бранденбурге сохранило средневековую церковь. На его территории работают учреждения медицинской и социальной помощи.","Это монастырь Ленин, по-немецки Lehnin."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/45.webp","alt":"Монастырь и уход · 45-тапсырмаға сурет","caption":"45-тапсырмаға сурет","width":113,"height":87}},{"number":46,"question":"Мына суретте берілген Л.ван Бетховенге арналған ерекше ескерткішті жасағанда полихромдық мүсінге табиғаты мен түсі әр түрлі материалдарды қосып, аралас әдіспен жұмыс істеген. Бұл ескерткіштің авторы кім?","choices":["Г.Кольбе","М.Клингер","Э.Барлах"],"answer":1,"title":"Скульптура из материалов","steps":["В памятнике фактура мрамора, бронзы и других материалов создаёт выразительные цветовые различия. Бетховен представлен сидящим, как античный герой.","Памятник создал Макс Клингер."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/46.webp","alt":"Скульптура из материалов · 46-тапсырмаға сурет","caption":"46-тапсырмаға сурет","width":111,"height":83}},{"number":47,"question":"Мына берілген суреттің авторы, Еуропа сурет өнерінде тұңғыш акварельді пейзаж салған суретшілердің бірі.","choices":["К.Д.Фридрих","А.Кауфман","А.Дюрер"],"answer":2,"title":"Акварель с натуры","steps":["Художник конца XV века оставил виды городов, гор и долин, написанные акварелью. Они показывают самостоятельный интерес к пейзажу.","Один из ранних европейских мастеров такого пейзажа — Альбрехт Дюрер."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/47.webp","alt":"Акварель с натуры · 47-тапсырмаға сурет","caption":"47-тапсырмаға сурет","detailSrc":"assets/golden-fleece/2013/interactive-9-11-kz/47-detail.webp","width":620,"height":415}},{"number":48,"question":"Мына берілген пейзаждың авторы ХІХ ғасырдың басындағы ең дарынды неміс суретшілерінің бірі болған, алайда оның өмірі шығармашылық жолының басында үзілген еді. Кім жайлы сөз болып отыр?","choices":["А.Граф","А.Менцель","К.Ф.Фор"],"answer":2,"title":"Ранний романтический пейзаж","steps":["Художник учился в Германии и работал в Италии. Он утонул в Тибре в 22 года, оставив небольшое число работ.","Речь о Карле Филиппе Форе."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/48.webp","alt":"Ранний романтический пейзаж · 48-тапсырмаға сурет","caption":"48-тапсырмаға сурет","width":118,"height":84}},{"number":49,"question":"Мына суреттің авторы он екі жыл бойы Берлин көркемсурет академиясының президенті болған. Ол кім?","choices":["М.Клингер","М.Либерман","Э.Нольде"],"answer":1,"title":"Президент академии","steps":["Пейзажист и портретист руководил Прусской академией художеств в 1920-е и начале 1930-х годов. Он также участвовал в Берлинском сецессионе.","Художника звали Макс Либерман."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/49.webp","alt":"Президент академии · 49-тапсырмаға сурет","caption":"49-тапсырмаға сурет","detailSrc":"assets/golden-fleece/2013/interactive-9-11-kz/49-detail.webp","width":620,"height":460}},{"number":50,"question":"Мына суреттің авторы өзінің көптеген акварельді суреттерін «жазылмаған суреттер» деп атаған. Бұл қай суретші?","choices":["Э.Нольде","А.Граф","П.Клее"],"answer":0,"title":"Малые акварели","steps":["В поздних небольших листах цветовые пятна изображают цветы и фантастические фигуры. Художник называл их «ненаписанными картинами».","Эта серия принадлежит Эмилю Нольде."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/50.webp","alt":"Малые акварели · 50-тапсырмаға сурет","caption":"50-тапсырмаға сурет","width":115,"height":84}},{"number":51,"question":"Г.Мюнтердің мына суретінде «Көк салт атты» бірлестігінің негізін қалаушылардың бірі болған қандай орыс суретшісі бейнеленген?","choices":["К.Малевич","В.Кандинский","А.Явленский"],"answer":1,"title":"Художник на портрете","steps":["Габриеле Мюнтер работала рядом с русским художником в Мурнау. Вместе с Францем Марком он подготовил альманах «Синий всадник».","На портрете показан Василий Кандинский."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/51.webp","alt":"Художник на портрете · 51-тапсырмаға сурет","caption":"51-тапсырмаға сурет","width":115,"height":87}},{"number":52,"question":"Берілген суреттің авторы график суретші, кескіндемеші, сондай-ақ Ф.Кутлердің «Ұлы Фридрихтің тарихы» тарихи шығармасына салынған иллюстрацияларымен де танымал. Бұл кім?","choices":["В.Лейбль","А.Менцель","А.Дюрер"],"answer":1,"title":"Иллюстратор историка","steps":["Для книги Куглера художник сделал сотни рисунков. Работа над историей Фридриха II повлияла и на сюжеты его картин.","Иллюстрации и картины создавал Адольф Менцель."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/52.webp","alt":"Иллюстратор историка · 52-тапсырмаға сурет","caption":"52-тапсырмаға сурет","width":115,"height":84}},{"number":53,"question":"Мына суреттің авторы Вена мемлекеттік операсының ішкі көрінісін салып танымал болған. Бұл қай суретші?","choices":["К.Д.Фридрих","В.фон Каульбах","М.фон Швинд"],"answer":2,"title":"Живописец венской оперы","steps":["Художник писал картины на сказочные и музыкальные сюжеты. Он участвовал и в росписях здания Венской оперы.","Речь о Морице фон Швинде."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/53.webp","alt":"Живописец венской оперы · 53-тапсырмаға сурет","caption":"53-тапсырмаға сурет","width":115,"height":91}},{"number":54,"question":"Мына ғибадатхананың авторы өзінің неоклассикалық стильдегі монументтік құрылыстарымен танымал болған. Бұл кім?","choices":["П.Беренс","К.Ф.Шинкель","Л.фон Кленце"],"answer":2,"title":"Неоклассические сооружения","steps":["Архитектор подражал античным ордерам и пропорциям. Крупные образцы его стиля — Вальхалла и Глиптотека.","Архитектора звали Лео фон Кленце."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/54.webp","alt":"Неоклассические сооружения · 54-тапсырмаға сурет","caption":"54-тапсырмаға сурет","width":115,"height":75}},{"number":55,"question":"Мына суретте көрсетілген сәулет өнері мен көркемдікөндірістік мектеп Германияда негізі қаланып, ХХ ғасыр өнеріндегі функционализмнің жарқын көрінісіне айналды. Ол қалай аталады?","choices":["Баухауз","Сецессион","Мост"],"answer":0,"title":"Форма по назначению","steps":["Школа объединяла художников, архитекторов и ремесленников. Мастерские искали, как форма мебели, здания или предмета отвечает его функции.","Школу основал Вальтер Гропиус и назвал Баухаузом."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/55.webp","alt":"Форма по назначению · 55-тапсырмаға сурет","caption":"55-тапсырмаға сурет","width":84,"height":115}},{"number":56,"question":"Мына суреттің авторы мүсіндерді билеп тұрған немесе діни жоралғыларды жасап тұрған қалпында симметриялы түрде орналастыру тән параллелизм стилін қалыптастырған. Бұл өнер иесі кім?","choices":["А.Бёклин","П.Клее","Ф.Ходлер"],"answer":2,"title":"Повтор фигур","steps":["Художник выстраивает фигуры в сходных позах и повторяет их жесты. Такой ритм объединяет всю композицию.","Свою систему швейцарец Фердинанд Ходлер называл параллелизмом."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/56.webp","alt":"Повтор фигур · 56-тапсырмаға сурет","caption":"56-тапсырмаға сурет","width":115,"height":63}},{"number":57,"question":"Мына суреттің авторы ағылшын королі ҮІІІ Генрих үшін оның көздеп отырған қалыңдықтарының портреттерін салған. Бұл суретші кім?","choices":["Кіші Г.Гольбейн","М.Грюневальд","Үлкен Л.Кранах"],"answer":0,"title":"Портреты для короля","steps":["Чтобы познакомиться с возможной невестой, Генрих VIII заказывал её портрет. Так появился известный портрет Анны Клевской.","Его написал Ганс Гольбейн Младший."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/57.webp","alt":"Портреты для короля · 57-тапсырмаға сурет","caption":"57-тапсырмаға сурет","width":87,"height":115}},{"number":58,"question":"Мына берілген суреттің авторы түс реңктеріне көп мән берген, тіпті, бұл мәселеге арнап «Түстер шеңбері» трактатын жазған. Кім жайлы сөз болып отыр?","choices":["К.Д.Фридрих","Ф.О.Рунге","А.Менцель"],"answer":1,"title":"Устройство цвета","steps":["Художник предложил располагать цвета в трёхмерном шаре и объяснял, как насыщенность меняется между белым и чёрным.","Учение о цвете разработал Филипп Отто Рунге."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/58.webp","alt":"Устройство цвета · 58-тапсырмаға сурет","caption":"58-тапсырмаға сурет","width":115,"height":85}},{"number":59,"question":"Мына суреттің авторы, өз жұмыстарын орыс суретшілері В.Кандинскиймен және А.Явленскиймен бірге көрмеге қойған швейцар суретшісі.","choices":["Ф.Ходлер","А.Бёклин","П.Клее"],"answer":2,"title":"Выставки в Мюнхене","steps":["Художник из Швейцарии вошёл в круг мюнхенских новаторов. Его работы показывали рядом с произведениями Кандинского и Явленского.","Имя художника — Пауль Клее."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/59.webp","alt":"Выставки в Мюнхене · 59-тапсырмаға сурет","caption":"59-тапсырмаға сурет","width":85,"height":115}},{"number":60,"question":"Мына портреттің авторы Орта ғасыр мен Ренессанс дәуіріндегі өнер мен өмір сүру салтына бағытталған «Назарейліктер» суретшілер бірлестігінің негізін қалаушы болған. Сөз болып отырған қай суретші?","choices":["Ф.Фейт","Ф.Пфорр","И.Ф.Овербек"],"answer":2,"title":"Круг назарейцев","steps":["Художники переселились в Рим и искали образцы в религиозной живописи раннего Возрождения. Они объединялись вокруг ясной линии и простоты рассказа.","Среди основателей братства был Иоганн Фридрих Овербек."],"figure":{"src":"assets/golden-fleece/2013/interactive-9-11-kz/60.webp","alt":"Круг назарейцев · 60-тапсырмаға сурет","caption":"60-тапсырмаға сурет","width":90,"height":115}}]);
